"""Standalone equivalents of shared Accounting and Cooperative contracts.
These are local-mode metadata only; MetaForge mode uses authorized server definitions.
"""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
types=[];registry={}
def add(code,title,module,fields,unique=None):
 mapping={'CODE':'code'};desc=[{'code':'code','type':'string','required':True,'target':None}]
 for alias,key,kind,target,required in fields:
  mapping[alias]=key;desc.append({'code':key,'type':kind,'required':required,'target':target})
 mapping['STATUS']='status';desc.append({'code':'status','type':'string','required':True,'target':None})
 registry[code]=mapping;types.append({'code':code,'name':title,'module':module,'description':'Shared standalone '+title,'fields':desc,'uniques':[['code']]+(unique or [])})
def f(alias,key,kind='string',target=None,required=True):return(alias,key,kind,target,required)
finance='cement_finance';people='cement_people'
add('account_type','Account Type',finance,[f('NAME','name'),f('CATEGORY','category')])
add('account','Account',finance,[f('NAME','name'),f('ACCOUNT_TYPE_ID','accountTypeId','reference','account_type'),f('CURRENCY','currency')])
add('fiscal_year','Fiscal Year',finance,[f('NAME','name'),f('START_DATE','startDate','date'),f('END_DATE','endDate','date')])
add('journal','Journal',finance,[f('POSTED_AT','postedAt','datetime'),f('SOURCE','source'),f('DESCRIPTION','description',required=False)])
add('journal_line','Journal Line',finance,[f('JOURNAL_ID','journalId','reference','journal'),f('ACCOUNT_ID','accountId','reference','account'),f('DEBIT','debit','number'),f('CREDIT','credit','number')])
add('account_balance','Account Balance',finance,[f('ACCOUNT_ID','accountId','reference','account'),f('BALANCE','balance','number')],[['accountId']])
add('bank_account','Bank Account',finance,[f('NAME','name'),f('ACCOUNT_ID','accountId','reference','account'),f('BANK_NAME','bankName'),f('ACCOUNT_NUMBER','accountNumber'),f('CURRENCY','currency')])
add('bank_statement','Bank Statement',finance,[f('BANK_ACCOUNT_ID','bankAccountId','reference','bank_account'),f('PERIOD_START','periodStart','date'),f('PERIOD_END','periodEnd','date'),f('OPENING_BALANCE','openingBalance','number'),f('CLOSING_BALANCE','closingBalance','number')])
add('bank_statement_line','Bank Statement Line',finance,[f('STATEMENT_ID','statementId','reference','bank_statement'),f('TRANSACTION_DATE','transactionDate','date'),f('DESCRIPTION','description'),f('AMOUNT','amount','number'),f('JOURNAL_ID','journalId','reference','journal',False)])
add('bank_reconciliation','Bank Reconciliation',finance,[f('STATEMENT_ID','statementId','reference','bank_statement'),f('RECONCILED_AT','reconciledAt','datetime',required=False),f('STATEMENT_BALANCE','statementBalance','number',required=False),f('LEDGER_BALANCE','ledgerBalance','number',required=False),f('DIFFERENCE','difference','number',required=False)])
add('member','Cooperative Member',people,[f('PERSON_ID','personId','reference','person'),f('MEMBER_NUMBER','memberNumber')],[['memberNumber']])
add('member_account','Cooperative Member Account',people,[f('MEMBER_ID','memberId','reference','member'),f('ACCOUNT_TYPE','accountType'),f('BALANCE_LIMIT','balanceLimit','number',required=False),f('BALANCE','balance','number',required=False)])
add('cooperative_transaction','Cooperative Transaction',people,[f('MEMBER_ACCOUNT_ID','memberAccountId','reference','member_account'),f('POSTING_DATE','postingDate','date'),f('AMOUNT','amount','number'),f('TRANSACTION_TYPE','transactionType'),f('SOURCE','source',required=False)])
(root/'resources/cement/shared_recordtypes.json').write_text(json.dumps(types,indent=2)+'\n')
(root/'resources/cement/shared_semantic_field_registry.json').write_text(json.dumps(registry,indent=2)+'\n')
(root/'frontend/src/registry/seededSharedFieldRegistry.js').write_text('// Generated by scripts/generate_shared.py. Local equivalents of shared schemas.\nexport const seededSharedFieldRegistry = Object.freeze('+json.dumps(registry,indent=2)+');\n')
